// CONCEPT 5: OUTPUT SAFETY & MODERATION
const item = ($input.first() && $input.first().json) ? $input.first().json : {};
const text = item.chatInput || item.message || item.prompt || 'Microservices provide modular deployment and independent scaling.';

const toxicityCheck = !text.toLowerCase().includes('toxic') && !text.toLowerCase().includes('malicious');
const lengthCheck = text.length > 5;
const outputApproved = toxicityCheck && lengthCheck;

return {
  json: {
    output: `🔍 [OUTPUT MODERATION AUDIT]\nText Audited: "${text}"\nContent Safety Status: ${outputApproved ? '🟢 CLEAN_APPROVED' : '🔴 FLAGGED_MODERATION'}\nToxicity Scan: Clean | Structural Check: Valid`,
    outputApproved
  }
};
